local TweenService = game:GetService("TweenService")
local module = {}

function module.In(obj: GuiObject, tweenInfo: TweenInfo?, callback)
    if obj:IsA("GuiObject") then
        local uiscale = Instance.new("UIScale", obj)
        uiscale.Scale = 2
        obj.Visible = true

        tweenInfo = tweenInfo or TweenInfo.new(.5, Enum.EasingStyle.Back, Enum.EasingDirection.Out)
        local anim = TweenService:Create(uiscale, tweenInfo, {Scale = 1})
        anim.Completed:Connect(function(playBackState)
            if playBackState == Enum.PlaybackState.Completed then
                uiscale:Destroy()
                if callback then
                    callback()
                end
            end
        end)
        anim:Play()

        return {
            Cancel = function()
                anim:Cancel()
                uiscale:Destroy()
            end
        }
    end
end

function module.Out(obj: GuiObject, tweenInfo: TweenInfo?, callback)
    if obj:IsA("GuiObject") then
        local uiscale = Instance.new("UIScale", obj)
        uiscale.Scale = 1
        obj.Visible = true

        tweenInfo = tweenInfo or TweenInfo.new(.5, Enum.EasingStyle.Back, Enum.EasingDirection.In)
        local anim = TweenService:Create(uiscale, tweenInfo, {Scale = 2})
        anim.Completed:Connect(function(playBackState)
            if playBackState == Enum.PlaybackState.Completed then
                uiscale:Destroy()
                obj.Visible = false
                if callback then
                    callback()
                end
            end
        end)
        anim:Play()

        return {
            Cancel = function()
                anim:Cancel()
                uiscale:Destroy()
            end
        }
    end
end

return module